#!/usr/bin/env node
// Builds every generated file from src/. Run it after any edit to src/.
//   tokens.css    custom properties for every theme, with a reduced-motion block
//   tokens.json   every token resolved, per theme
//   tokens.js     the same values as a JavaScript module
//   tailwind.css  a Tailwind v4 theme carrying the same roles
//   fonts.css     @font-face rules, when a family lists font files
//   figma.json    the payload a Figma sync pushes
//   ../DESIGN.md  frontmatter and motion table, when the file exists (and DESIGN.dark.md)
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { ROOT, BRAND, loadThemes, walk, aliasOf, resolveValue, cssName, publicPath, tierOf, ext, dim, get } from './lib/tokens.mjs';
import { toCss, toHex } from './lib/color.mjs';
import { figmaPayload } from './lib/figma.mjs';
import { designFrontmatter, motionTable, spliceDesign } from './lib/design-md.mjs';

const HELP = `Usage: node scripts/build.mjs [--verify]

Builds every generated file in this folder from src/, and refreshes the frontmatter of
../DESIGN.md when that file exists.

Options:
  --verify   Write nothing. Exit 1 if any generated file differs from a fresh build
  --help     Show this text

Exit codes: 0 built or verified, 1 a file is stale (--verify), 2 the source could not be read.`;
const args = process.argv.slice(2);
if (args.includes('--help')) { console.log(HELP); process.exit(0); }
const verify = args.includes('--verify');

let loaded;
try { loaded = loadThemes(); } catch (e) { console.error(`Error: ${e.message}`); process.exit(2); }
// An alias that points nowhere stops the build with one line, never a stack trace.
process.on('uncaughtException', (e) => { console.error(`Error: ${e.message}. Fix it in src/ and build again.`); process.exit(2); });
const { themes, defaultTheme } = loaded;
const names = Object.keys(themes);
const other = names.filter((n) => n !== defaultTheme);
const NOTE = 'Generated by scripts/build.mjs from src/. Do not edit: change src/ and build again.';

const rem = (v) => (v && typeof v === 'object' && v.unit === 'px' ? `${+(v.value / 16).toFixed(4)}rem` : dim(v));
const REM = /^brand\.(font-size|line-height)\./;
const family = (v) => (Array.isArray(v) ? v : [v]).map((f) => (/[\s]/.test(f) ? `"${f}"` : f)).join(', ');

// One CSS value per token type. An alias becomes var(), so the chain stays visible in the browser.
function cssValue(path, token, type, tree) {
  const a = aliasOf(token);
  // A color that aliases another may set its own opacity in $extensions["brand-os"].alpha, for a
  // scrim or a veil. The value is then written out, since var() cannot carry an opacity.
  if (a && type === 'color' && ext(token).alpha !== undefined) {
    const r = resolveValue(tree, token.$value);
    return { value: toCss({ ...r, alpha: ext(token).alpha }) };
  }
  if (a) return { value: `var(${cssName(a)})` };
  const v = token.$value;
  switch (type) {
    case 'color': {
      const modern = toCss(v);
      const alpha = typeof v === 'object' && v.alpha !== undefined && v.alpha < 1;
      return modern.startsWith('#') || alpha ? { value: modern } : { value: toHex(v), modern };
    }
    case 'dimension': {
      // A size may shrink on a small viewport: $extensions["brand-os"].fluid = { min, from, to },
      // all in px. It ships as a clamp between two rem values, so browser zoom still works. from and
      // to default to brand.viewport.min and max, so every fluid value grows across one range.
      const f = ext(token).fluid;
      if (f && v.unit === 'px') {
        const vp = (k, d) => { const t = tree.brand?.viewport?.[k]; const r = t && resolveValue(tree, t.$value); return r && typeof r === 'object' ? r.value : d; };
        const [from, to] = [f.from ?? vp('min', 375), f.to ?? vp('max', 1280)];
        const slope = (v.value - f.min) / (to - from);
        const intercept = f.min - slope * from;
        return { value: `clamp(${+(f.min / 16).toFixed(4)}rem, ${+(intercept / 16).toFixed(4)}rem + ${+(slope * 100).toFixed(4)}vw, ${+(v.value / 16).toFixed(4)}rem)` };
      }
      return { value: REM.test(path) ? rem(v) : dim(v) };
    }
    case 'duration': return { value: dim(v) };
    case 'number': return { value: path.startsWith('brand.tracking.') ? `${v}em` : `${v}` };
    case 'fontWeight': return { value: `${v}` };
    case 'fontFamily': return { value: family(v) };
    case 'cubicBezier': return { value: `cubic-bezier(${v.join(', ')})` };
    case 'shadow': {
      // A shadow may alias a color token and set its own opacity in $extensions["brand-os"].alpha,
      // one number, or one per layer. The color is then typed once.
      const alphas = [ext(token).alpha].flat();
      const layers = (Array.isArray(v) ? v : [v]).map((s, i) => {
        const r = resolveValue(tree, s);
        const a = alphas[i] ?? alphas[0];
        if (a !== undefined && r.color && typeof r.color === 'object') r.color = { ...r.color, alpha: a };
        return `${r.inset ? 'inset ' : ''}${dim(r.offsetX)} ${dim(r.offsetY)} ${dim(r.blur)} ${dim(r.spread)} ${toCss(r.color)}`;
      });
      return { value: layers.join(', ') };
    }
    case 'string': return { value: v };
    default: throw new Error(`No CSS rule for $type ${type} at ${path}`);
  }
}

function typographyLines(path, token) {
  const n = cssName(path);
  const part = (k) => {
    const raw = token.$value[k];
    const m = typeof raw === 'string' && raw.match(/^\{([^}]+)\}$/);
    return m ? `var(${cssName(m[1])})` : null;
  };
  const v = token.$value;
  const lines = [
    [`${n}-font-family`, part('fontFamily') ?? family(v.fontFamily)],
    [`${n}-font-size`, part('fontSize') ?? rem(v.fontSize)],
    [`${n}-font-weight`, part('fontWeight') ?? `${v.fontWeight}`],
    [`${n}-line-height`, part('lineHeight') ?? rem(v.lineHeight)],
    [`${n}-letter-spacing`, part('letterSpacing') ?? `${v.letterSpacing}em`],
  ];
  const e = ext(token);
  if (e.fontFeatureSettings) lines.push([`${n}-font-feature-settings`, e.fontFeatureSettings]);
  // The font shorthand resets width, so a role that sets one also names it as its own property.
  if (e.fontStretch) lines.push([`${n}-font-stretch`, e.fontStretch]);
  if (e.textTransform) lines.push([`${n}-text-transform`, e.textTransform]);
  lines.push([n, `var(${n}-font-weight) var(${n}-font-size) / var(${n}-line-height) var(${n}-font-family)`]);
  return lines;
}

function declarations(tree, keep) {
  const base = [];
  const modern = [];
  for (const [p, token, type] of walk(tree)) {
    const path = p.join('.');
    if (!keep(path)) continue;
    if (type === 'typography') { for (const [k, v] of typographyLines(path, token)) base.push(`  ${k}: ${v};`); continue; }
    const c = cssValue(path, token, type, tree);
    base.push(`  ${cssName(path)}: ${c.value};`);
    if (c.modern) modern.push(`    ${cssName(path)}: ${c.modern};`);
  }
  return { base, modern };
}

function block(selector, { base, modern }, indent = '') {
  if (!base.length) return '';
  let s = `${indent}${selector} {\n${base.map((l) => indent + l).join('\n')}\n${indent}}\n`;
  if (modern.length)
    s += `${indent}@supports (color: oklch(0% 0 0)) {\n${indent}  ${selector} {\n${modern.map((l) => indent + l).join('\n')}\n${indent}  }\n${indent}}\n`;
  return s;
}

// Reduced motion is not a theme: each duration names its reduced value in an extension.
function reduced(tree) {
  const lines = [];
  for (const [p, token] of walk(tree)) {
    const r = ext(token)['reduced-motion'];
    if (r) lines.push(`    ${cssName(p.join('.'))}: ${r.startsWith('{') ? `var(${cssName(r.slice(1, -1))})` : r};`);
  }
  return lines.length ? `@media (prefers-reduced-motion: reduce) {\n  :root {\n${lines.join('\n')}\n  }\n}\n` : '';
}

const isCore = (p) => tierOf(p) === 'brand';
const themed = (p) => tierOf(p) !== 'brand';
const base = themes[defaultTheme].tree;
const { brands, themeNames, defaultBrand, defaultThemeName } = loaded;
const ctx = (b, t) => Object.values(themes).find((c) => c.brand === b && c.theme === t);
const otherThemes = themeNames.filter((t) => t !== defaultThemeName);
const otherBrands = brands.filter((b) => b !== defaultBrand);
// With sub-brands, a theme's roles are declared again on every element that sets a sub-brand, so
// each var() resolves against that sub-brand's Intent rather than the one inherited from :root.
const under = (sel) => (otherBrands.length ? `${sel},\n${sel} [data-brand],\n${sel}[data-brand]` : sel);

// tokens.css: Brand on :root, then the default sub-brand's Intent and the default theme's Patterns.
// Another sub-brand is set by data-brand, another theme by data-theme. A dark theme also follows the
// system preference unless the page pins the default one.
let css = `/* ${NOTE} */\n` + block(':root', declarations(base, isCore));
const defaults = [':root', ...(otherThemes.length ? [`[data-theme="${defaultThemeName}"]`] : []), ...(otherBrands.length ? [`[data-brand="${defaultBrand}"]`] : [])];
css += block(defaults.join(',\n'), declarations(base, themed));
for (const b of otherBrands) {
  // A sub-brand's block holds the Intent its own file sets, and every Patterns role again.
  const c = ctx(b, defaultThemeName);
  if (!c) continue;
  const mine = (path) => tierOf(path) === 'patterns' || (tierOf(path) === 'intent' && c.brandOwn.includes(c.origin[path]));
  css += block(`[data-brand="${b}"]`, declarations(c.tree, mine));
}
for (const t of otherThemes) {
  // A theme's block holds only what its own file sets. Everything else is inherited from :root.
  const c = ctx(defaultBrand, t);
  if (!c) continue;
  const mine = (path) => themed(path) && c.own.includes(c.origin[path]);
  const d = declarations(c.tree, mine);
  css += block(under(`[data-theme="${t}"]`), d);
  if (t === 'dark' || defaultThemeName === 'dark') {
    const scheme = t === 'dark' ? 'dark' : 'light';
    css += `@media (prefers-color-scheme: ${scheme}) {\n${block(under(`:root:not([data-theme="${defaultThemeName}"])`), d, '  ')}}\n`;
  }
}
css += reduced(base);

// tokens.json and tokens.js: every token resolved, keyed by its CSS name without the dashes.
function resolved(tree) {
  const out = {};
  for (const [p, token, type] of walk(tree)) {
    const path = p.join('.');
    const name = cssName(path).slice(2);
    const v = resolveValue(tree, token.$value);
    if (type === 'color') {
      const a = ext(token).alpha;
      out[name] = a !== undefined ? toCss({ ...v, alpha: a }) : typeof v === 'object' && v.alpha !== undefined && v.alpha < 1 ? toCss(v) : toHex(v);
    }
    else if (type === 'typography')
      out[name] = { fontFamily: family(v.fontFamily), fontSize: dim(v.fontSize), fontWeight: v.fontWeight, lineHeight: dim(v.lineHeight), letterSpacing: `${v.letterSpacing}em`, ...(ext(token).textTransform ? { textTransform: ext(token).textTransform } : {}), ...(ext(token).fontFeatureSettings ? { fontFeatureSettings: ext(token).fontFeatureSettings } : {}), ...(ext(token).fontStretch ? { fontStretch: ext(token).fontStretch } : {}) };
    else if (type === 'shadow') out[name] = cssValue(path, { $value: v }, 'shadow', tree).value;
    else if (type === 'fontFamily') out[name] = family(v);
    else if (type === 'cubicBezier') out[name] = `cubic-bezier(${v.join(', ')})`;
    else if (type === 'number' && path.startsWith('brand.tracking.')) out[name] = `${v}em`;
    else out[name] = v && typeof v === 'object' && 'unit' in v ? dim(v) : v;
  }
  return out;
}
// What each role points at, and the facts the sheet and the checks read: ramps, scale, units.
function meta(tree) {
  const core = tree.brand ?? {};
  const ramps = {};
  const fixed = {};
  for (const [name, ramp] of Object.entries(core.color ?? {})) {
    if (name.startsWith('$')) continue;
    if ('$value' in ramp) { fixed[name] = toHex(ramp.$value); continue; }
    ramps[name] = { ...(ext(ramp).ramp ?? {}), steps: Object.fromEntries(Object.entries(ramp).filter(([k]) => !k.startsWith('$')).map(([k, t]) => [k, { hex: toHex(t.$value), oklch: t.$value.components ?? null }])) };
  }
  // aliases: each Patterns role and the Brand step it lands on, through Intent. intent: each role
  // and the Intent step it names. intentRamps: which Brand ramp each Intent ramp uses here.
  const aliases = {};
  const intent = {};
  const intentRamps = {};
  const toBrand = (a) => { let t = a; for (let i = 0; i < 8 && t && tierOf(t) !== 'brand'; i++) t = aliasOf(get(tree, t) ?? {}); return t; };
  for (const [p, token] of walk(tree)) {
    const path = p.join('.');
    const a = aliasOf(token);
    if (!a) continue;
    if (tierOf(path) === 'patterns') {
      const b = toBrand(a);
      if (b) aliases[cssName(path).slice(2)] = cssName(b).slice(2);
      if (tierOf(a) === 'intent') intent[cssName(path).slice(2)] = cssName(a).slice(2);
    }
    if (tierOf(path) === 'intent' && p[1] === 'color' && tierOf(a) === 'brand') intentRamps[p[2]] ??= a.split('.')[2];
  }
  // layers: every published name and its layer, which the audit reads to find unused tokens. keep:
  // names a brand marked as used outside this folder, $extensions["brand-os"].keep with the reason.
  const layers = {};
  const keep = {};
  for (const [p, token] of walk(tree)) {
    const n = cssName(p.join('.')).slice(2);
    layers[n] = tierOf(p.join('.'));
    if (ext(token).keep) keep[n] = ext(token).keep;
  }
  return { ramps, fixed, proportion: ext(tree.patterns?.color).proportion ?? null, scale: ext(core['font-size']).scale ?? null, unit: ext(core.spacing).unit ?? null, aliases, intent, intentRamps, layers, keep, placeholder: ext(core).placeholder ?? [] };
}
const json = { $note: NOTE, default: defaultTheme, themes: Object.fromEntries(names.map((n) => [n, resolved(themes[n].tree)])), meta: Object.fromEntries(names.map((n) => [n, meta(themes[n].tree)])) };
const js = `// ${NOTE}\nexport const tokens = ${JSON.stringify(json.themes, null, 2)};\nexport const defaultTheme = ${JSON.stringify(defaultTheme)};\nexport const cssVar = (name) => \`var(--\${name})\`;\nexport default tokens[defaultTheme];\n`;

// tailwind.css: a Tailwind v4 theme. Import it in place of tokens.css. Each namespace it defines is
// reset first, so a utility the brand never defined stops resolving.
function tailwind() {
  const t = resolved(base);
  const L = [];
  const add = (k, v) => L.push(`  ${k}: ${v};`);
  add('--color-*', 'initial');
  for (const [k] of Object.entries(t)) if (k.startsWith('color-') && themedName(k)) add(`--${k}`, `var(--${k})`);
  add('--font-*', 'initial');
  for (const [k] of Object.entries(t)) if (k.startsWith('font-family-')) add(`--font-${k.slice(12)}`, `var(--${k})`);
  add('--text-*', 'initial');
  for (const [k, v] of Object.entries(t))
    if (k.startsWith('type-') && typeof v === 'object') {
      const r = k.slice(5);
      add(`--text-${r}`, `var(--${k}-font-size)`);
      add(`--text-${r}--line-height`, `var(--${k}-line-height)`);
    }
  add('--radius-*', 'initial');
  for (const [k] of Object.entries(t)) if (k.startsWith('radius-')) add(`--${k}`, `var(--${k})`);
  add('--shadow-*', 'initial');
  for (const [k] of Object.entries(t)) if (k.startsWith('elevation-')) add(`--shadow-${k.slice(10)}`, `var(--${k})`);
  add('--ease-*', 'initial');
  for (const [k] of Object.entries(t)) if (k.startsWith('motion-easing-')) add(`--ease-${k.slice(14)}`, `var(--${k})`);
  if (t['spacing-1']) add('--spacing', 'var(--spacing-1)');
  // Named spacing steps, such as the fluid gutter and section padding, become p-gutter, py-section.
  for (const [k] of Object.entries(t)) if (/^spacing-[a-z]/.test(k)) add(`--${k}`, `var(--${k})`);
  // Content widths join Tailwind's own sizes, max-w-content and max-w-prose. The namespace is not
  // reset: component libraries built on Tailwind use its max-w-sm to max-w-7xl.
  for (const [k] of Object.entries(t)) if (k.startsWith('container-')) add(`--${k}`, `var(--${k})`);
  // A media query cannot read a custom property, so breakpoints are written as values.
  if (Object.keys(t).some((k) => k.startsWith('breakpoint-'))) {
    add('--breakpoint-*', 'initial');
    for (const [k, v] of Object.entries(t)) if (k.startsWith('breakpoint-')) add(`--${k}`, /px$/.test(v) ? `${+(parseFloat(v) / 16).toFixed(4)}rem` : v);
  }
  return `/* ${NOTE} */\n/* Tailwind v4. Load tokens.css first, then this file after @import "tailwindcss". */\n@theme inline {\n${L.join('\n')}\n}\n`;
}
// Work references Patterns only, so only Patterns colors become utilities: bg-bg-page, never a ramp.
const appliedNames = new Set([...walk(base)].filter(([p]) => tierOf(p.join('.')) === 'patterns').map(([p]) => cssName(p.join('.')).slice(2)));
const themedName = (k) => appliedNames.has(k);

// fonts.css: a family lists its files in $extensions["brand-os"].files.
function fonts() {
  const rules = [];
  for (const [p, token, type] of walk(base)) {
    if (type !== 'fontFamily') continue;
    const name = (Array.isArray(token.$value) ? token.$value : [token.$value])[0];
    for (const f of ext(token).files ?? [])
      rules.push(`@font-face {\n  font-family: "${name}";\n  src: url("../${String(f.src).replace(/^brand\//, '')}") format("${f.format ?? ({ ttf: 'truetype', otf: 'opentype', woff: 'woff', woff2: 'woff2' }[String(f.src).split('.').pop().toLowerCase()] ?? 'woff2')}");\n  font-weight: ${f.weight ?? 400};${f.stretch ? `\n  font-stretch: ${f.stretch};` : ''}\n  font-style: ${f.style ?? 'normal'};\n  font-display: swap;\n}`);
  }
  return rules.length ? `/* ${NOTE} */\n${rules.join('\n')}\n` : null;
}

const files = {
  'tokens.css': css,
  'tokens.json': JSON.stringify(json, null, 2) + '\n',
  'tokens.js': js,
  'tailwind.css': tailwind(),
  'figma.json': JSON.stringify(figmaPayload(themes, defaultTheme), null, 2) + '\n',
};
const f = fonts();
if (f) files['fonts.css'] = f;

// DESIGN.md: the frontmatter and the motion table are generated into the prose the brand wrote.
const design = [];
for (const [theme, file] of [[defaultTheme, 'DESIGN.md'], ...other.map((t) => [t, `DESIGN.${t.replace("/", ".")}.md`])]) {
  const path = resolve(BRAND, file);
  if (!existsSync(path)) continue;
  const next = spliceDesign(readFileSync(path, 'utf8'), designFrontmatter(themes[theme].tree), motionTable(themes[theme].tree));
  design.push([path, file, next]);
}

const stale = [];
for (const [name, content] of Object.entries(files)) {
  const path = resolve(ROOT, name);
  if (verify) { if (!existsSync(path) || readFileSync(path, 'utf8') !== content) stale.push(name); }
  else writeFileSync(path, content);
}
for (const [path, file, next] of design) {
  if (verify) { if (readFileSync(path, 'utf8') !== next) stale.push(`../${file}`); }
  else writeFileSync(path, next);
}
if (verify) {
  if (stale.length) { console.error(`Stale: ${stale.join(', ')}. Run node scripts/build.mjs.`); process.exit(1); }
  console.log(JSON.stringify({ verified: Object.keys(files).length + design.length }));
} else {
  // A kit scaled by an earlier scale.mjs keeps a "computed" note on every step, and a Figma push
  // carries it into each variable's description. Name the fix rather than edit src/ from a build.
  const core = JSON.parse(readFileSync(resolve(ROOT, 'src/brand.tokens.json'), 'utf8')).brand ?? {};
  const old = ['font-size', 'line-height'].flatMap((g) => Object.entries(core[g] ?? {}).filter(([k, t]) => !k.startsWith('$') && /px computed\s*$/.test(t?.$description ?? '')).map(([k]) => `${g}.${k}`));
  console.log(JSON.stringify({ themes: names, default: defaultTheme, ...(otherBrands.length ? { brands } : {}), wrote: [...Object.keys(files), ...design.map((d) => `../${d[1]}`)], ...(old.length ? { oldScaleNotes: `${old.length} type steps carry the old "computed" note. Run node scripts/scale.mjs --tidy.` } : {}) }));
}
